#include <bits/stdc++.h>
using namespace std;

namespace io {
    static const int S = 1<<20;
    static char b[S];
    static int p=0,l=0;
    inline char gc(){
        if(p==l){ l=(int)fread(b,1,S,stdin); p=0; if(l<=0) return 0; }
        return b[p++];
    }
    inline int readInt(){
        char c=gc();
        while(c<'0'||c>'9'){ if(!c) return 0; c=gc(); }
        int x=0;
        while(c>='0'&&c<='9'){ x=x*10+(c-'0'); c=gc(); }
        return x;
    }
}

const int MAXN = 1<<21;
const int MAXE = 2*((1<<21)-1) + 10;
int head[MAXN], to[MAXE], nxt[MAXE];
int par[MAXN], sz[MAXN], ord[MAXN];
unsigned char F[MAXN];

int main(){
    int t = io::readInt();
    while(t--){
        int n = io::readInt();
        int N = 1<<n;
        for(int i=0;i<N;i++) head[i]=-1;
        int ec=0;
        for(int i=0;i<N-1;i++){
            int u=io::readInt(), v=io::readInt();
            to[ec]=v; nxt[ec]=head[u]; head[u]=ec++;
            to[ec]=u; nxt[ec]=head[v]; head[v]=ec++;
        }
        int qh=0, qt=0;
        ord[qt++]=0; par[0]=-1;
        while(qh<qt){
            int u=ord[qh++];
            for(int e=head[u]; e!=-1; e=nxt[e]){
                int v=to[e];
                if(v==par[u]) continue;
                par[v]=u;
                ord[qt++]=v;
            }
        }
        for(int i=0;i<N;i++){ sz[i]=1; F[i]=0; }
        for(int idx=N-1; idx>=1; --idx){
            int v=ord[idx];
            int p=par[v];
            sz[p]+=sz[v];
            int s=sz[v]&3;
            if(s==1||s==2) F[p]^=1;
        }
        for(int m=1;m<N;m++){
            int s=(N-sz[m])&3;
            if(s==2||s==3) F[m]^=1;
        }
        int base = (n==1)?1:0;
        int ans=0;
        for(int m=0;m<N;m++) if(base ^ F[m]) ans^=m;
        printf("%d\n", ans);
    }
    return 0;
}
